# Read-only companion: 3D controls never mutate preparation or analysis settings.
cell_profile <- function(d, sample) {
  if (is.null(d) || !nrow(d) || length(sample) != 1 || !sample %in% names(d)) return(data.frame())
  lipid <- as.character(d[[1]]); value <- suppressWarnings(as.numeric(d[[sample]])); cls <- rd_class(lipid); cls[is.na(cls)|!nzchar(cls)] <- "Unclassified"
  out <- do.call(rbind, lapply(split(seq_along(value), cls), function(ix) { ok <- is.finite(value[ix]) & value[ix] >= 0; data.frame(Class=cls[ix[1]], Abundance=if(any(ok))sum(value[ix][ok]) else NA_real_, Features=length(ix), Available=sum(ok), Excluded=sum(!ok)) }))
  total <- sum(out$Abundance,na.rm=TRUE); out$Signal_percent <- if(total>0) 100*out$Abundance/total else NA_real_; out$Log10_signal <- ifelse(out$Abundance>0,log10(out$Abundance),NA_real_); out$Sample <- sample; out$Basis <- "Prepared feature signal; class inferred from annotation prefix; not molar fraction"; out[order(out$Abundance,decreasing=TRUE,na.last=TRUE),,drop=FALSE]
}
cell_metadata_groups <- function(d, meta, preferred=NULL) {
  samples <- if(is.null(d))character()else names(d)[-1]; empty <- data.frame(Measurement=samples,Group=rep(NA_character_,length(samples)),Group_column=rep(NA_character_,length(samples)),Metadata_unmatched=rep(FALSE,length(samples)),Metadata_ambiguous=rep(FALSE,length(samples))); if(!length(samples))return(empty)
  if(is.null(meta)||!nrow(meta)) {empty$Metadata_unmatched<-TRUE;return(empty)}; keys <- intersect(c("FullName","Sample","Measurement","DisplayLabel"),names(meta)); if(!length(keys)) {empty$Metadata_unmatched<-TRUE;return(empty)}; coverage<-vapply(keys,function(k)sum(samples%in%as.character(meta[[k]]),na.rm=TRUE),numeric(1)); key<-keys[which.max(coverage)]
  candidates <- names(meta)[vapply(meta,function(x)is.atomic(x)&&!is.list(x),logical(1))]; candidates <- setdiff(candidates,c(key,"DisplayLabel","Sample")); candidates <- candidates[vapply(candidates,function(n){u<-length(unique(stats::na.omit(as.character(meta[[n]]))));u>=2&&u<sum(!is.na(meta[[n]]))},logical(1))]
  ranked <- intersect(c("Dynamic_DE_Group","Group1","Group2","TimePoint"),candidates)
  col <- if(!is.null(preferred)&&preferred%in%candidates) preferred else if(length(ranked)) ranked[1] else candidates[1]; if(!length(col)||is.na(col)) {empty$Metadata_unmatched<-TRUE;return(empty)}
  key_values<-as.character(meta[[key]]); duplicate<-!is.na(key_values)&(duplicated(key_values)|duplicated(key_values,fromLast=TRUE)); ix<-match(samples,key_values); ambiguous<-!is.na(ix)&duplicate[ix]; ix[ambiguous]<-NA_integer_; data.frame(Measurement=samples,Group=as.character(meta[[col]][ix]),Group_column=col,Metadata_unmatched=is.na(ix),Metadata_ambiguous=ambiguous)
}
