cell_descriptive_feature_rank <- function(d, groups, reference, comparison, selected_lipid = NULL) {
  empty <- data.frame(Lipid=character(),Class=character(),Reference_n=integer(),Comparison_n=integer(),Reference_median=numeric(),Comparison_median=numeric(),Median_difference=numeric(),Absolute_median_difference=numeric(),stringsAsFactors=FALSE)
  if (is.null(d) || !nrow(d) || ncol(d) < 3 || is.null(groups) || !nrow(groups) || length(reference) != 1 || length(comparison) != 1 || identical(as.character(reference),as.character(comparison))) return(empty)
  samples <- names(d)[-1]; sample_groups <- as.character(groups$Group[match(samples,groups$Measurement)])
  selected_lipid <- as.character(selected_lipid); selected_lipid <- selected_lipid[!is.na(selected_lipid)]
  labels <- as.character(d[[1]]); duplicate <- duplicated(labels) | duplicated(labels,fromLast=TRUE)
  pieces <- lapply(seq_len(nrow(d)),function(i) { lipid <- labels[i]; if (is.na(lipid) || !nzchar(lipid) || duplicate[i] || lipid %in% selected_lipid) return(NULL); signal <- suppressWarnings(as.numeric(d[i,-1,drop=TRUE])); ref <- signal[sample_groups==reference]; cmp <- signal[sample_groups==comparison]; ref <- ref[is.finite(ref)]; cmp <- cmp[is.finite(cmp)]; if (length(ref)<3 || length(cmp)<3) return(NULL); ref_median <- stats::median(ref); cmp_median <- stats::median(cmp); difference <- cmp_median-ref_median; data.frame(Lipid=lipid,Class=rd_class(lipid),Reference_n=length(ref),Comparison_n=length(cmp),Reference_median=ref_median,Comparison_median=cmp_median,Median_difference=difference,Absolute_median_difference=abs(difference),stringsAsFactors=FALSE) })
  out <- do.call(rbind,pieces); candidate_count <- sum(!labels %in% selected_lipid)
  if (is.null(out) || !nrow(out)) out <- empty else out <- out[order(-out$Absolute_median_difference,out$Lipid),,drop=FALSE]
  attr(out,"candidate_count") <- candidate_count; attr(out,"skipped_count") <- max(0L,candidate_count-nrow(out));out
}
cell_clicked_sample <- function(hit, shown, samples) {
  sample <- as.character(hit$customdata %||% NA_character_)
  if (length(sample) == 1 && isTRUE(sample %in% shown$Measurement) && sample %in% samples) sample else NA_character_
}
cell_explore_selection <- function(choice, current_class) {
  if (is.null(choice) || !nrow(choice)) return(NULL)
  list(Class=as.character(choice$Class[1]),Lipid=as.character(choice$Lipid[1]),same_class=identical(as.character(choice$Class[1]),as.character(current_class)))
}
