 output$cell_comparison_status<-renderUI({v<-selected_values();a<-summary_one(v,input$cell_reference_group);b<-summary_one(v,input$cell_comparison_group);dirty<-tryCatch(shared_data$preparation_dirty(),error=function(e)NA);partial<-if("Partial_total"%in%names(v))sum(v$Partial_total%in%TRUE,na.rm=TRUE)else 0;unmatched<-sum(group_frame()$Metadata_unmatched%in%TRUE,na.rm=TRUE);div(class="cell-profile-note",if(isTRUE(dirty))div(class="cell-preparation-dirty",strong("Settings have changed. "),"This comparison still shows the last applied prepared run. Rerun Quality to apply changes."),if(is.na(dirty))tags$p("Preparation freshness is unavailable; values are labeled from the current prepared matrix."),strong("Reference vs Comparison"),if(any(display_group(c(input$cell_reference_group,input$cell_comparison_group))!=c(input$cell_reference_group,input$cell_comparison_group)))tags$p("Sickle cell is the display label for the original group Exp in this study. Source labels are unchanged."),tags$p(paste0("Reference: ",display_group(input$cell_reference_group)," (n=",a$n,")")),tags$p(paste0("Comparison: ",display_group(input$cell_comparison_group)," (n=",b$n,")")),if(unmatched>0)tags$p(paste0(unmatched," sample(s) could not be matched uniquely to metadata and were omitted.")),if(partial>0)tags$p(paste0(partial," displayed class total(s) are partial: negative, nonfinite or missing class features were excluded; available/excluded feature counts are in the CSV.")),tags$p("This view has not established per-value raw/imputed/outlier-replaced provenance; markers do not infer it."),tags$p("Individual points and violin densities are descriptive prepared values; no significance test is calculated in this 3D companion."))})
 output$cell_comparison_plot<-plotly::renderPlotly({v<-selected_values();validate(need(!identical(as.character(input$cell_reference_group),as.character(input$cell_comparison_group)),"Choose two different groups."),need(nrow(v)>0&&any(is.finite(v$Prepared_signal)),"Select two metadata groups with available prepared values."));v$Display_group<-display_group(v$Group);v$Plot_group<-ifelse(v$Group==input$cell_reference_group,"Reference","Comparison");v$Plot_group<-factor(v$Plot_group,levels=c("Reference","Comparison"));counts<-table(v$Plot_group[is.finite(v$Prepared_signal)]);kind<-if(length(counts)<2||min(counts)<8)"box" else "violin";args<-list(data=v,x=~Plot_group,y=~Prepared_signal,customdata=~Measurement,type=kind,jitter=.18,pointpos=0,color=~Plot_group,colors=c("#176b73","#c55432"),source="cell_comparison_points",text=~paste0(Measurement,"<br>",Display_group,"<br>Prepared signal: ",signif(Prepared_signal,6),"<br>Click to inspect this measurement"),hoverinfo="text");if(kind=="violin"){args$points<-"all";args$spanmode<-"hard";args$marker<-list(color="#162230",size=5,opacity=.8);args$box<-list(visible=TRUE);args$meanline<-list(visible=TRUE)}else args$boxpoints<-"all";do.call(plotly::plot_ly,args)|>plotly::layout(title=list(text=paste0("Prepared signal · ",if(kind=="box")"box + points (n < 8)" else "violin + points","<br>Click a point for its single-measurement profile · descriptive comparison"),font=list(size=12)),yaxis=list(title="Prepared abundance signal"),xaxis=list(title=""),showlegend=FALSE,margin=list(l=60,r=12,b=45,t=58),paper_bgcolor="white",plot_bgcolor="white")|>plotly::config(displaylogo=FALSE,responsive=TRUE)})
