 output$cell_comparison_payload<-renderUI({v<-tryCatch(selected_values(),error=function(e)data.frame());a<-summary_one(v,input$cell_reference_group);b<-summary_one(v,input$cell_comparison_group);cp<-tryCatch(class_comparison(),error=function(e)data.frame());cp<-cp[cp$Class==input$cell_class,,drop=FALSE];ca<-summary_one(data.frame(Group=cp$Group,Prepared_signal=cp$Abundance),input$cell_reference_group);cb<-summary_one(data.frame(Group=cp$Group,Prepared_signal=cp$Abundance),input$cell_comparison_group);dirty<-tryCatch(shared_data$preparation_dirty(),error=function(e)NA);selected_name<-if(identical(input$cell_explore_level,"class"))paste0(input$cell_class%||%""," class total")else input$cell_lipid%||%"";payload<-list(evidence="measured",preparation_dirty=if(is.na(dirty))NULL else isTRUE(dirty),taxonomy=list(measured="Prepared feature values and supplied metadata labels.",interpreted="Lipid-class annotation and reference cell biology.",simulated="Cinematic controls are conceptual only; no biological simulation is running."),comparison=list(group_column=input$cell_group_column%||%"",label=paste(input$cell_reference_group%||%"","vs",input$cell_comparison_group%||%""),reference=input$cell_reference_group%||%"",comparison=input$cell_comparison_group%||%"",reference_display=display_group(input$cell_reference_group%||%""),comparison_display=display_group(input$cell_comparison_group%||%""),reference_n=a$n,comparison_n=b$n),selection=list(class=input$cell_class%||%"",feature=selected_name),class_summary=list(class=input$cell_class%||%"",reference_median=ca$median,comparison_median=cb$median,reference_n=ca$n,comparison_n=cb$n),feature_summary=list(reference_median=a$median,comparison_median=b$median,reference_n=a$n,comparison_n=b$n),note="Measured cohort values are shown beside an illustrative reference cell; no organelle localization is inferred.");json<-jsonlite::toJSON(payload,auto_unbox=TRUE,null="null",na="null");json<-gsub("<","\\u003c",json,fixed=TRUE);tags$script(id="cel